+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Snake Game</title>
+    <style>
+        body {
+            display: flex;
+            justify-content: center;
+            align-items: center;
+            min-height: 100vh;
+            margin: 0;
+            padding: 20px;
+            background: #090d16;
+        }
+        .game-container {
+            background: rgba(16, 24, 40, 0.75);
+            backdrop-filter: blur(20px);
+            padding: 20px;
+            border-radius: 10px;
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.4);
+        }
+        .game-header {
+            display: flex;
+            justify-content: space-between;
+            padding: 12px 20px;
+        }
+        .score {
+            font-family: 'Inter', sans-serif;
+            font-size: 24px;
+            color: #fff;
+        }
+        .high-score {
+            font-family: 'Inter', sans-serif;
+            font-size: 24px;
+            color: #fff;
+        }
+        .game-over-overlay {
+            display: none;
+            position: absolute;
+            top: 0;
+            left: 0;
+            width: 100%;
+            height: 100%;
+            background: rgba(0, 0, 0, 0.5);
+            justify-content: center;
+            align-items: center;
+        }
+        .game-over-text {
+            font-family: 'Inter', sans-serif;
+            font-size: 36px;
+            color: #fff;
+        }
+        .start-game-overlay {
+            display: flex;
+            position: absolute;
+            top: 0;
+            left: 0;
+            width: 100%;
+            height: 100%;
+            background: rgba(0, 0, 0, 0.5);
+            justify-content: center;
+            align-items: center;
+        }
+        .start-game-text {
+            font-family: 'Inter', sans-serif;
+            font-size: 36px;
+            color: #fff;
+        }
+        .play-button {
+            font-family: 'Inter', sans-serif;
+            font-size: 24px;
+            color: #fff;
+            background: #3498db;
+            border: none;
+            padding: 10px 20px;
+            border-radius: 10px;
+            cursor: pointer;
+        }
+        .play-button:hover {
+            background: #2ecc71;
+        }
+    </style>
+</head>
+<body>
+    <div class="game-container">
+        <div class="game-header">
+            <span class="score">Score: 0</span>
+            <span class="high-score">High Score: 0</span>
+        </div>
+        <canvas id="gameCanvas" width="400" height="400"></canvas>
+        <div class="game-over-overlay">
+            <span class="game-over-text">Game Over!</span>
+            <button class="play-button" id="replay-button">Replay</button>
+        </div>
+        <div class="start-game-overlay">
+            <span class="start-game-text">Welcome to Snake Game!</span>
+            <button class="play-button" id="start-button">Start Game</button>
+        </div>
+    </div>
+    <script>
+        const canvas = document.getElementById('gameCanvas');
+        const ctx = canvas.getContext('2d');
+        const scoreElement = document.querySelector('.score');
+        const highScoreElement = document.querySelector('.high-score');
+        const gameOverOverlay = document.querySelector('.game-over-overlay');
+        const startGameOverlay = document.querySelector('.start-game-overlay');
+        const replayButton = document.getElementById('replay-button');
+        const startButton = document.getElementById('start-button');
+        let score = 0;
+        let highScore = 0;
+        let snake = [
+            { x: 200, y: 200 },
+            { x: 190, y: 200 },
+            { x: 180, y: 200 }
+        ];
+        let direction = 'right';
+        let food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+        let intervalId;
+        
+        function drawSnake() {
+            ctx.clearRect(0, 0, canvas.width, canvas.height);
+            for (let i = 0; i < snake.length; i++) {
+                ctx.fillStyle = 'rgba(56, 189, 248, 0.4)';
+                ctx.fillRect(snake[i].x, snake[i].y, 10, 10);
+            }
+        }
+        
+        function drawFood() {
+            ctx.fillStyle = 'rgba(255, 105, 97, 0.4)';
+            ctx.fillRect(food.x, food.y, 10, 10);
+        }
+        
+        function update() {
+            for (let i = snake.length - 1; i > 0; i--) {
+                snake[i] = { ...snake[i - 1] };
+            }
+            if (direction === 'right') {
+                snake[0].x += 10;
+            } else if (direction === 'left') {
+                snake[0].x -= 10;
+            } else if (direction === 'up') {
+                snake[0].y -= 10;
+            } else if (direction === 'down') {
+                snake[0].y += 10;
+            }
+            
+            if (snake[0].x === food.x && snake[0].y === food.y) {
+                score++;
+                scoreElement.textContent = `Score: ${score}`;
+                food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+                snake.push({ x: snake[snake.length - 1].x, y: snake[snake.length - 1].y });
+            }
+            
+            if (snake[0].x < 0 || snake[0].x >= canvas.width || snake[0].y < 0 || snake[0].y >= canvas.height || checkCollision()) {
+                gameOver();
+            }
+            
+            drawSnake();
+            drawFood();
+        }
+        
+        function checkCollision() {
+            for (let i = 1; i < snake.length; i++) {
+                if (snake[0].x === snake[i].x && snake[0].y === snake[i].y) {
+                    return true;
+                }
+            }
+            return false;
+        }
+        
+        function gameOver() {
+            clearInterval(intervalId);
+            gameOverOverlay.style.display = 'flex';
+            if (score > highScore) {
+                highScore = score;
+                highScoreElement.textContent = `High Score: ${highScore}`;
+                localStorage.setItem('highScore', highScore);
+            }
+        }
+        
+        function startGame() {
+            startGameOverlay.style.display = 'none';
+            score = 0;
+            scoreElement.textContent = `Score: ${score}`;
+            snake = [
+                { x: 200, y: 200 },
+                { x: 190, y: 200 },
+                { x: 180, y: 200 }
+            ];
+            direction = 'right';
+            food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+            intervalId = setInterval(update, 100);
+        }
+        
+        document.addEventListener('keydown', (e) => {
+            if (e.key === 'ArrowRight' && direction !== 'left') {
+                direction = 'right';
+            } else if (e.key === 'ArrowLeft' && direction !== 'right') {
+                direction = 'left';
+            } else if (e.key === 'ArrowUp' && direction !== 'down') {
+                direction = 'up';
+            } else if (e.key === 'ArrowDown' && direction !== 'up') {
+                direction = 'down';
+            }
+        });
+        
+        replayButton.addEventListener('click', startGame);
+        startButton.addEventListener('click', startGame);
+        
+        if (localStorage.getItem('highScore')) {
+            highScore = parseInt(localStorage.getItem('highScore'));
+            highScoreElement.textContent = `High Score: ${highScore}`;
+        }
+    </script>
+</body>
+</html>

